/**
 * Quiet-hours deferral for outbound SMS.
 * 47 CFR 64.1200(c)(1): generally 8:00–21:00 in the called party's local time.
 * Florida & Oklahoma: end at 20:00.
 * Defer (reschedule next_send_at) — never drop.
 *
 * When the lead zone is unknown or ambiguous (multiple candidates), require
 * EVERY candidate zone AND the business zone to be open; otherwise defer or
 * mark unresolved (send nothing).
 */

export const QUIET_START_HOUR = 8;
export const QUIET_END_HOUR_DEFAULT = 21; // exclusive
export const QUIET_END_HOUR_FL_OK = 20; // exclusive

import { AREA_CODE_ZONES, FL_AREA, OK_AREA } from './quiet-hours-zones';


const VALID_TZ_CACHE = new Map<string, boolean>();

export function isValidTimeZone(tz: string): boolean {
  if (VALID_TZ_CACHE.has(tz)) return VALID_TZ_CACHE.get(tz)!;
  try {
    Intl.DateTimeFormat('en-US', { timeZone: tz }).format(new Date());
    VALID_TZ_CACHE.set(tz, true);
    return true;
  } catch {
    VALID_TZ_CACHE.set(tz, false);
    return false;
  }
}

export function areaCodeFromE164(e164: string): string | null {
  const digits = e164.replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1, 4);
  if (digits.length === 10) return digits.slice(0, 3);
  return null;
}

export type LeadTimezoneResolution = {
  zones: string[];
  ambiguous: boolean;
  known: boolean;
  endHour: number;
};

export function resolveLeadTimezones(opts: {
  callerPhoneE164?: string | null;
  leadTimezone?: string | null;
  businessTimezone?: string | null;
}): LeadTimezoneResolution {
  const ac = opts.callerPhoneE164
    ? areaCodeFromE164(opts.callerPhoneE164)
    : null;
  const endHour = endHourForAreaCode(ac);

  // Explicit lead timezone always wins when valid.
  const leadTz = opts.leadTimezone?.trim() || '';
  if (leadTz && isValidTimeZone(leadTz)) {
    return {
      zones: [leadTz],
      ambiguous: false,
      known: true,
      endHour,
    };
  }

  const mapped = ac ? AREA_CODE_ZONES[ac] : undefined;
  if (mapped) {
    const zones = mapped.filter(isValidTimeZone);
    if (zones.length > 1) {
      // Ambiguous (e.g. 850 ET+CT): require EVERY zone open.
      return { zones, ambiguous: true, known: true, endHour };
    }
    if (zones.length === 1) {
      return { zones, ambiguous: false, known: true, endHour };
    }
  }

  // Unmapped / missing area code → UNRESOLVED. Never fall back to business TZ.
  void opts.businessTimezone;
  return { zones: [], ambiguous: false, known: false, endHour };
}

/** @deprecated Prefer resolveLeadTimezones */
export function resolveLeadTimezone(opts: {
  callerPhoneE164?: string | null;
  leadTimezone?: string | null;
  businessTimezone?: string | null;
}): string {
  const r = resolveLeadTimezones(opts);
  return r.zones[0] || 'America/New_York';
}

export function endHourForAreaCode(ac: string | null): number {
  if (ac && (FL_AREA.has(ac) || OK_AREA.has(ac))) return QUIET_END_HOUR_FL_OK;
  return QUIET_END_HOUR_DEFAULT;
}

export function quietEndHourForPhone(callerPhoneE164?: string | null): number {
  const ac = callerPhoneE164 ? areaCodeFromE164(callerPhoneE164) : null;
  return endHourForAreaCode(ac);
}

export function localParts(
  instant: Date,
  timeZone: string
): { year: number; month: number; day: number; hour: number; minute: number; second: number; weekday: string } {
  if (!isValidTimeZone(timeZone)) {
    throw new Error(`Invalid time zone: ${timeZone}`);
  }
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    weekday: 'short',
    hourCycle: 'h23',
  });
  const parts = Object.fromEntries(
    fmt.formatToParts(instant).map((p) => [p.type, p.value])
  );
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour),
    minute: Number(parts.minute),
    second: Number(parts.second),
    weekday: String(parts.weekday),
  };
}

export function isWithinQuietHoursWindow(
  instant: Date,
  timeZone: string,
  endHourExclusive: number
): boolean {
  const { hour } = localParts(instant, timeZone);
  return hour >= QUIET_START_HOUR && hour < endHourExclusive;
}

/**
 * Next UTC instant whose local time in `timeZone` is exactly `hour:00:00`,
 * strictly after `from` (or equal if from is already exactly that).
 * Aligns to minute boundaries so 7:59:59 → 8:00:00 (not 8:00:59).
 */
export function nextLocalHour(
  from: Date,
  timeZone: string,
  hour: number
): Date {
  // Stryker disable all: exact-hour short-circuit + minute-walk (covered by nextLocalHour tests).
  const p0 = localParts(from, timeZone);
  if (p0.hour === hour && p0.minute === 0 && p0.second === 0) return from;

  // Align minute-walk:
  // Align to the next whole UTC minute (avoids landing on :59 forever).
  let t = Math.ceil((from.getTime() + 1) / 60_000) * 60_000;
  for (let i = 0; i < 60 * 50; i++) {
    const p = localParts(new Date(t), timeZone);
    if (p.hour === hour && p.minute === 0) return new Date(t);
    t += 60_000;
  }
  return new Date(from.getTime() + 24 * 60 * 60 * 1000);
  // Stryker restore all
}

export type QuietHoursDecision =
  | { allowed: true; zones: string[] }
  | {
      allowed: false;
      nextSendAt: Date;
      zones: string[];
      endHour: number;
      unresolved?: false;
    }
  | {
      allowed: false;
      unresolved: true;
      reason: string;
      zones: string[];
    };

export function deferUntilQuietHoursOpen(
  now: Date,
  opts: {
    callerPhoneE164?: string | null;
    leadTimezone?: string | null;
    businessTimezone?: string | null;
  }
): QuietHoursDecision {
  const resolution = resolveLeadTimezones(opts);
  if (resolution.zones.length === 0) {
    return {
      allowed: false,
      unresolved: true,
      reason: 'no_valid_timezone',
      zones: [],
    };
  }

  // Ambiguous / unknown: every candidate zone must be open.
  const allOpen = resolution.zones.every((tz) =>
    isWithinQuietHoursWindow(now, tz, resolution.endHour)
  );
  if (allOpen) {
    return { allowed: true, zones: resolution.zones };
  }

  // Next send = latest next-open across all zones (when all are open together).
  // Stryker disable all: multi-zone search loop — covered by deferUntilQuietHoursOpen tests.
  let next = now;
  for (let guard = 0; guard < 48; guard++) {
    const candidates = resolution.zones.map((tz) =>
      isWithinQuietHoursWindow(next, tz, resolution.endHour)
        ? next
        : nextLocalHour(next, tz, QUIET_START_HOUR)
    );
    const latest = new Date(Math.max(...candidates.map((d) => d.getTime())));
    const ok = resolution.zones.every((tz) =>
      isWithinQuietHoursWindow(latest, tz, resolution.endHour)
    );
    if (ok) {
      return {
        allowed: false,
        nextSendAt: latest,
        zones: resolution.zones,
        endHour: resolution.endHour,
      };
    }
    // Nudge forward 1 minute past latest and retry
    next = new Date(latest.getTime() + 60_000);
  }
  // Stryker restore all

  return {
    allowed: false,
    unresolved: true,
    reason: 'cannot_align_windows',
    zones: resolution.zones,
  };
}

src/services/opt-out.ts.source:
/**
 * TCPA / carrier opt-out detection.
 * Whole-message match after NFKC + confusable folding + zero-width strip.
 * Shared normalizer is also the source of truth for migration 003 STOP backfill.
 */

import {
  AMBIGUOUS,
  CONFUSABLES,
  OPT_OUT_COMPACT,
  OPT_OUT_EXACT,
} from './opt-out-data';

export type OptOutVerdict =
  | { kind: 'opt_out' }
  | { kind: 'ambiguous'; reason: string }
  | { kind: 'not_opt_out' };

export { OPT_OUT_EXACT, OPT_OUT_COMPACT };

const ZERO_WIDTH_RE =
  /[\u200B-\u200D\uFEFF\u2060\u180E\u00AD\u034F\u061C\u115F\u1160\u17B4\u17B5\u3164\uFFA0]/g;

export function foldConfusables(raw: string): string {
  let out = '';
  for (const ch of raw) {
    out += CONFUSABLES[ch] ?? ch;
  }
  return out;
}

/**
 * Canonical normalizer used by inbound webhook AND migration 003 backfill
 * (SQL approximates the same steps — see 003_campaign_idempotency.sql).
 */
export function normalizeOptOutText(raw: string): string {
  // Stryker disable next-line all -- chained Unicode transforms; covered by fixture strings
  return foldConfusables(raw)
    .normalize('NFKC')
    .replace(ZERO_WIDTH_RE, '')
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '')
    .replace(/\u00a0/g, ' ')
    .trim()
    .replace(/^["'`“”‘’]+|["'`“”‘’]+$/g, '')
    .replace(/[?!.,…]+$/g, '')
    .replace(/\s+/g, ' ')
    .toUpperCase();
}

/** Spaceless form so 'S T O P' and 'STOP STOP' compact to STOP / STOPSTOP. */
export function compactOptOutText(normalized: string): string {
  return normalized.replace(/ /g, '');
}

/**
 * Classify an inbound body for opt-out.
 * Exact whole-message match only for auto opt-out.
 */
export function classifyOptOut(raw: string): OptOutVerdict {
  const normalized = normalizeOptOutText(raw);
  // Stryker disable next-line conditionalExpression -- empty → not_opt_out is equivalent to fallthrough
  if (!normalized) return { kind: 'not_opt_out' };

  for (const token of OPT_OUT_EXACT) {
    if (normalized === token) return { kind: 'opt_out' };
  }

  const compact = compactOptOutText(normalized);
  if (OPT_OUT_COMPACT.has(compact)) return { kind: 'opt_out' };

  // Service-talk short-circuit is equivalent to fallthrough for current
  // AMBIGUOUS set (both yield not_opt_out); keep the guard for clarity and
  // ignore equivalent ConditionalExpression/BlockStatement mutants.
  // Stryker disable next-line ConditionalExpression,BlockStatement
  if (isServiceTalkWithStop(normalized)) {
    // Stryker disable next-line ObjectLiteral
    return { kind: 'not_opt_out' };
  }

  // Stryker disable all -- ambiguous regex table + Unicode prep
  const cleanedRaw = foldConfusables(raw)
    .normalize('NFKC')
    .replace(ZERO_WIDTH_RE, '')
    .trim();
  for (const re of AMBIGUOUS) {
    if (re.test(cleanedRaw) && normalized !== 'STOP') {
      return { kind: 'ambiguous', reason: 'needs_human_review' };
    }
  }
  // Stryker restore all

  return { kind: 'not_opt_out' };
}

/** True when STOP appears inside service language (not an opt-out). */
export function isServiceTalkWithStop(normalized: string): boolean {
  // Early exits are boolean-equivalent to falling through for bare STOP /
  // no-STOP inputs (later OR-chain is false). Ignore those mutants; the
  // OR-chain itself is killed by positive + negative STOP fixtures.
  // Stryker disable next-line ConditionalExpression
  if (normalized === 'STOP') return false;
  // Stryker disable next-line ConditionalExpression
  if (!/\bSTOP\b/.test(normalized)) return false;
  return (
    /^(WON'?T|CANT|CAN'T|DOESN'?T|DIDN'?T|NEVER)\b/.test(normalized) ||
    /\bSTOP\s+(BY|IN|AT|THE|LEAKING|DRIPPING|COMING)\b/.test(normalized) ||
    /\b(WON'?T|DOESN'?T)\s+STOP\b/.test(normalized)
  );
}

/** True only for definite auto opt-out. */
export function isDefiniteOptOut(raw: string): boolean {
  return classifyOptOut(raw).kind === 'opt_out';
}

/**
 * Tokens (already-normalized) that migration 003 should treat as STOP.
 * Kept in sync with classifyOptOut / OPT_OUT_EXACT + compact forms.
 */
export function optOutBackfillTokens(): string[] {
  const set = new Set<string>([...OPT_OUT_EXACT, ...OPT_OUT_COMPACT]);
  return [...set];
}

export const OPT_OUT_FOOTER = 'Reply STOP to opt out.';

src/services/reconcile-logic.ts.source:
/**
 * Pure send/reconcile state machine decisions (no I/O).
 *
 * Advance on duplicate sid ONLY if that row is confirmed sent (not failed).
 * Requeue ONLY on explicit never_sent AND key_supported_at_send.
 * Older/pre-key rows → needs_review, never requeue.
 */

import {
  isConfirmedSmsStatus,
  isFailedSmsStatus,
  parseMessageSid,
  type ParsedSid,
  type RelayLookupOutcome,
} from '@/services/sms-sid';

export type DuplicateSidDecision =
  | { action: 'advance' }
  | { action: 'park' }
  | { action: 'needs_review' };

export function decideOnDuplicateSid(
  existingStatus: string | null | undefined
): DuplicateSidDecision {
  if (isFailedSmsStatus(existingStatus)) return { action: 'needs_review' };
  if (isConfirmedSmsStatus(existingStatus)) return { action: 'advance' };
  return { action: 'park' };
}

export type ReconcileRowDecision =
  | {
      action: 'confirm';
      providerStatus: string;
      parsed: ParsedSid;
    }
  | {
      action: 'requeue_campaign';
      enrollmentId: string;
      campaignId: string;
      stepNumber: number;
    }
  | { action: 'requeue_recovery'; leadId: string }
  | { action: 'park' }
  | { action: 'needs_review'; reason?: string };

/** Max unknown reconcile attempts before needs_review. */
export const MAX_RECONCILE_ATTEMPTS = 5;

/**
 * Normalize a raw relay lookup (may lack `outcome`) into a safe outcome.
 * found:true + status=failed → failed.
 * found:true without outcome → sent (unless failed).
 * found:false without outcome → never_sent.
 * Missing outcome / silence → unknown (never invent never_sent).
 */
export function normalizeLookupOutcome(lookup: {
  outcome?: RelayLookupOutcome | string | null;
  found?: boolean;
  status?: string;
  id?: string;
}): { outcome: RelayLookupOutcome; providerStatus: string } {
  const status = lookup.status || 'queued';

  if (
    lookup.outcome === 'sent' ||
    lookup.outcome === 'never_sent' ||
    lookup.outcome === 'unknown' ||
    lookup.outcome === 'failed'
  ) {
    if (lookup.outcome === 'sent' && isFailedSmsStatus(status)) {
      return { outcome: 'failed', providerStatus: status };
    }
    return { outcome: lookup.outcome, providerStatus: status };
  }

  if (lookup.found === true) {
    if (isFailedSmsStatus(status)) {
      return { outcome: 'failed', providerStatus: status };
    }
    if (lookup.id || lookup.status) {
      return { outcome: 'sent', providerStatus: status };
    }
  }
  if (lookup.found === false) {
    return { outcome: 'never_sent', providerStatus: 'queued' };
  }
  return { outcome: 'unknown', providerStatus: status };
}

export function decideReconcileRow(opts: {
  sid: string;
  outcome: RelayLookupOutcome | string | null | undefined;
  providerStatus?: string;
  reconcileAttempts?: number;
  /** True only when this row was sent after key support was confirmed (or key echoed). */
  keySupportedAtSend?: boolean | null;
}): ReconcileRowDecision {
  const parsed = parseMessageSid(opts.sid);
  const attempts = opts.reconcileAttempts ?? 0;

  if (opts.outcome === 'failed') {
    return { action: 'needs_review', reason: 'relay_status_failed' };
  }

  if (opts.outcome === 'sent') {
    if (isFailedSmsStatus(opts.providerStatus)) {
      return { action: 'needs_review', reason: 'relay_status_failed' };
    }
    return {
      action: 'confirm',
      providerStatus: opts.providerStatus || 'queued',
      parsed,
    };
  }

  // ONLY explicit never_sent may requeue — and ONLY if the row was keyed
  // after lookup support was confirmed. Pre-upgrade / rollback rows → review.
  if (opts.outcome === 'never_sent') {
    if (!opts.keySupportedAtSend) {
      return {
        action: 'needs_review',
        reason: 'never_sent_without_key_support',
      };
    }
    if (parsed.kind === 'campaign') {
      return {
        action: 'requeue_campaign',
        enrollmentId: parsed.enrollmentId,
        campaignId: parsed.campaignId,
        stepNumber: parsed.stepNumber,
      };
    }
    if (parsed.kind === 'recovery') {
      return { action: 'requeue_recovery', leadId: parsed.leadId };
    }
    return { action: 'park' };
  }

  // unknown / missing / anything else → park (or needs_review after N attempts)
  if (attempts + 1 >= MAX_RECONCILE_ATTEMPTS) {
    return { action: 'needs_review', reason: 'max_attempts' };
  }
  return { action: 'park' };
}

src/services/send/machine.ts.source:
/**
 * Pure send/reconcile state machine.
 *
 * Lifecycle:
 *   queued → sent | never_sent | ambiguous → (reconcile) → resolved | needs_review
 *
 * Transitions are total and deterministic — property-tested with fast-check.
 */

export const MAX_RECONCILE_ATTEMPTS = 5;

/** Base park interval (5 min); doubles each attempt, capped at 6h. */
export const PARK_BASE_MS = 5 * 60 * 1000;
export const PARK_MAX_MS = 6 * 60 * 60 * 1000;

export type RelaySendSignal =
  | { type: 'ok'; messageId: string; status: string; keyEchoed: boolean; duplicate?: boolean }
  | { type: 'conflict' }
  | { type: 'rate_limit' }
  | { type: 'maintenance' }
  | { type: 'failed'; status?: string }
  | { type: 'error' };

export type RelayLookupSignal =
  | { type: 'sent'; status: string }
  | { type: 'never_sent' }
  | { type: 'failed'; status: string }
  | { type: 'unknown' };

export type SendRowPhase =
  | 'queued'
  | 'sending'
  | 'sent'
  | 'never_sent'
  | 'ambiguous'
  | 'needs_review'
  | 'resolved';

export type SendMachineEvent =
  | { kind: 'send_result'; signal: RelaySendSignal; capsBeforeSend: boolean }
  | { kind: 'lookup'; signal: RelayLookupSignal; keySupportedAtSend: boolean; attempts: number };

export type SendMachineDecision =
  | {
      action: 'confirm_sent';
      providerStatus: string;
      keySupportedAtSend: boolean;
      phase: 'sent';
    }
  | { action: 'park_ambiguous'; reason: string; phase: 'ambiguous'; nextAttempts: number }
  | { action: 'needs_review'; reason: string; phase: 'needs_review' }
  | { action: 'requeue_never_sent'; phase: 'never_sent' }
  | { action: 'resolved'; providerStatus: string; phase: 'resolved' };

export function parkDelayMs(reconcileAttempts: number): number {
  const exp = Math.max(0, reconcileAttempts);
  const raw = PARK_BASE_MS * 2 ** exp;
  return Math.min(raw, PARK_MAX_MS);
}

export function parkNextAt(
  reconcileAttempts: number,
  now: Date = new Date()
): Date {
  return new Date(now.getTime() + parkDelayMs(reconcileAttempts));
}

/**
 * Apply a send or lookup event to the row state machine.
 * Does not perform I/O — callers persist the decision.
 */
export function transitionSend(event: SendMachineEvent): SendMachineDecision {
  if (event.kind === 'send_result') {
    return onSendResult(event.signal, event.capsBeforeSend);
  }
  return onLookup(
    event.signal,
    event.keySupportedAtSend,
    event.attempts
  );
}

function onSendResult(
  signal: RelaySendSignal,
  capsBeforeSend: boolean
): SendMachineDecision {
  switch (signal.type) {
    case 'ok': {
      if (signal.duplicate && isFailedStatus(signal.status)) {
        return { action: 'needs_review', reason: 'duplicate_failed', phase: 'needs_review' };
      }
      if (isFailedStatus(signal.status)) {
        return { action: 'needs_review', reason: 'relay_failed', phase: 'needs_review' };
      }
      return {
        action: 'confirm_sent',
        providerStatus: signal.status || 'queued',
        keySupportedAtSend: capsBeforeSend && signal.keyEchoed,
        phase: 'sent',
      };
    }
    case 'conflict':
      return { action: 'needs_review', reason: 'idempotency_conflict', phase: 'needs_review' };
    case 'failed':
      return { action: 'needs_review', reason: 'relay_failed', phase: 'needs_review' };
    case 'rate_limit':
      return {
        action: 'park_ambiguous',
        reason: 'recent_send',
        phase: 'ambiguous',
        nextAttempts: 0,
      };
    case 'maintenance':
      return {
        action: 'park_ambiguous',
        reason: 'maintenance',
        phase: 'ambiguous',
        nextAttempts: 0,
      };
    case 'error':
    default:
      return {
        action: 'park_ambiguous',
        reason: 'send_error',
        phase: 'ambiguous',
        nextAttempts: 0,
      };
  }
}

function onLookup(
  signal: RelayLookupSignal,
  keySupportedAtSend: boolean,
  attempts: number
): SendMachineDecision {
  switch (signal.type) {
    case 'sent':
      if (isFailedStatus(signal.status)) {
        return { action: 'needs_review', reason: 'relay_status_failed', phase: 'needs_review' };
      }
      return {
        action: 'resolved',
        providerStatus: signal.status || 'queued',
        phase: 'resolved',
      };
    case 'failed':
      return { action: 'needs_review', reason: 'relay_status_failed', phase: 'needs_review' };
    case 'never_sent':
      if (!keySupportedAtSend) {
        return {
          action: 'needs_review',
          reason: 'never_sent_without_key_support',
          phase: 'needs_review',
        };
      }
      return { action: 'requeue_never_sent', phase: 'never_sent' };
    case 'unknown':
    default: {
      const next = attempts + 1;
      if (next >= MAX_RECONCILE_ATTEMPTS) {
        return { action: 'needs_review', reason: 'max_attempts', phase: 'needs_review' };
      }
      return {
        action: 'park_ambiguous',
        reason: 'lookup_unknown',
        phase: 'ambiguous',
        nextAttempts: next,
      };
    }
  }
}

export function isFailedStatus(status: string | null | undefined): boolean {
  return Boolean(status && String(status).toLowerCase() === 'failed');
}

export function isConfirmedStatus(status: string | null | undefined): boolean {
  if (!status) return false;
  return ['queued', 'dispatched', 'sent', 'delivered'].includes(status);
}

export function isAmbiguousStatus(status: string | null | undefined): boolean {
  return Boolean(status && ['sending', 'unknown'].includes(status));
}

/** Recovery resolution used to gate campaign step 1. */
export type RecoveryResolvedOutcome =
  | 'resolved_sent'
  | 'resolved_abandoned'
  | 'pending'
  | 'absent';

export function classifyRecoveryStatus(
  status: string | null | undefined
): RecoveryResolvedOutcome {
  if (!status) return 'absent';
  if (isConfirmedStatus(status)) return 'resolved_sent';
  if (status === 'abandoned_retry') return 'resolved_abandoned';
  if (
    isAmbiguousStatus(status) ||
    status === 'needs_review' ||
    isFailedStatus(status)
  ) {
    return 'pending';
  }
  return 'absent';
}

