      capabilities: { relay: 'dry-run', version: 'test', idempotency: true },
    }),
  }),
}));

vi.mock('@/lib/messaging/brwn-relay', async () => {
  const actual = await vi.importActual<typeof import('@/lib/messaging/brwn-relay')>(
    '@/lib/messaging/brwn-relay'
